-- Migration 0008: استبدال بنك أسئلة المحاسبة الكامل
-- المصدر: docs/بنك_الأسئلة_الشامل_المحاسبة_2026.docx
-- المحتوى: 61 سؤالاً جديداً (سهل 37 / متوسط 17 / متقدم 7) — إجابة صحيحة واحدة لكل سؤال
-- حُذفت 10 أسئلة متعددة الإجابات (اختر 2/3) لأن المنصة تدعم إجابة واحدة فقط:
--   Q13, Q14, Q17, Q26, Q34, Q35, Q43, Q45, Q60, Q68
-- ملاحظة: حذف الأسئلة القديمة يستلزم حذف بيانات محاولات قسم المحاسبة المرتبطة بها (FK).

begin;

-- 1) إجابات المحاولات الخاصة بأسئلة المحاسبة
delete from public.attempt_answers aa
using public.attempt_questions aq
join public.questions q on q.id = aq.question_id
join public.categories c on c.id = q.category_id
where c.slug = 'accounting'
  and aa.attempt_question_id = aq.id;

-- 2) لقطات أسئلة المحاسبة داخل المحاولات
delete from public.attempt_questions aq
using public.questions q
join public.categories c on c.id = q.category_id
where c.slug = 'accounting'
  and aq.question_id = q.id;

-- 3) المحاولات التي أصبحت بلا أسئلة
delete from public.quiz_attempts att
where not exists (select 1 from public.attempt_questions aq where aq.attempt_id = att.id);

-- 4) الخيارات والأسئلة القديمة
delete from public.question_options o
using public.questions q
join public.categories c on c.id = q.category_id
where c.slug = 'accounting'
  and o.question_id = q.id;

delete from public.questions q
using public.categories c
where q.category_id = c.id
  and c.slug = 'accounting';

-- 5) الأسئلة الجديدة
insert into public.questions (id, category_id, question_text, explanation, difficulty, is_active, created_at, updated_at)
