  ('90064eb71bf8b19cb11f65a199e6c3fc'::uuid, E'خلال كم شهرًا من تاريخ الميزانية العمومية يُعتبر الالتزام التزامًا متداولاً (Current Liability)؟', NULL, 'easy'),
